actions.script:
ec.web?.response?.setHeader('Cache-Control', 'no-store, private')
ec.web?.response?.setHeader('Pragma', 'no-cache')
String company = related.userCompanyPartyId?.toString()
String allowedCompany = System.getenv('NASQO_ACCOUNTING_STAGE_COMPANY')
review = [available: false, status: 'NO_SAVED_REVIEW', readOnly: true]
if (allowedCompany && company == allowedCompany) {
    def helper = ec.resource.script(
        'component://growerp/service/NasqoSavedAccountingReview.groovy', null)
    review = helper.read(new File('/var/lib/nasqo-accounting-imports'), company)
    if (review.available) {
        def imports = ec.entity.find('growerp.nasqo.AccountingImportDocument')
            .condition('companyPartyId',company).list()
        if (imports) {
            def invoiceIds=imports*.invoiceId.findAll{it}
            def invoices=ec.entity.find('mantle.account.invoice.Invoice')
                .condition('invoiceId',org.moqui.entity.EntityCondition.IN,invoiceIds).list()
            long ledgerCount=ec.entity.find('mantle.ledger.transaction.AcctgTrans')
                .condition('invoiceId',org.moqui.entity.EntityCondition.IN,invoiceIds).count()
            def paymentImports=ec.entity.find('growerp.nasqo.AccountingImportPayment')
                .condition('companyPartyId',company).list()
            def paymentIds=paymentImports*.paymentId.findAll{it}
            def payments=paymentIds ? ec.entity.find('mantle.account.payment.Payment')
                .condition('paymentId',org.moqui.entity.EntityCondition.IN,paymentIds).list() : []
            if(paymentIds) ledgerCount+=ec.entity.find('mantle.ledger.transaction.AcctgTrans')
                .condition('paymentId',org.moqui.entity.EntityCondition.IN,paymentIds).count()
            review.financialDocumentsCreated=invoices.size()+payments.size()
            review.postedEntries=ledgerCount
            review.status='NATIVE_DRAFTS_CREATED_NOT_POSTED'
            review.nativeImport=[
                invoiceCount:invoices.size(),paymentCount:payments.size(),
                paymentDirections:paymentImports.countBy{it.direction},
                paymentStatuses:payments.countBy{it.statusId},
                paymentReferences:payments.take(12).collect{[paymentId:it.paymentId,reference:it.pseudoId,invoiceId:it.forInvoiceId]},
                invoiceItems:ec.entity.find('mantle.account.invoice.InvoiceItem')
                    .condition('invoiceId',org.moqui.entity.EntityCondition.IN,invoiceIds).count(),
                heldMovements:review.summary.movements-imports.size()-paymentImports.size(),
                sourceDocumentTypes:imports.countBy{it.sourceBillType},
                draftStatuses:invoices.countBy{it.statusId},
                sampleReferences:invoices.take(12).collect{[invoiceId:it.invoiceId,reference:it.pseudoId]}]
        }
    }

}
